1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="description" content="An accessible, animated pulsing circle with adjustable speed and pause controls.">
7	  <meta name="color-scheme" content="dark">
8	  <title>Pulsing Circle</title>
9	  <style>
10	    :root {
11	      --circle-hue: #8ec5ff;
12	      --circle-core: #4a7dd9;
13	      --circle-shadow: #1f3a75;
14	      --cycle: 2.5s;
15	    }
16	    * {
17	      margin: 0;
18	      padding: 0;
19	      box-sizing: border-box;
20	    }
21	    body {
22	      width: 100vw;
23	      height: 100vh;
24	      height: 100dvh;
25	      display: flex;
26	      flex-direction: column;
27	      justify-content: center;
28	      align-items: center;
29	      gap: 24px;
30	      background: radial-gradient(circle at center, #1a1a2e 0%, #0d0d17 100%);
31	      overflow: hidden;
32	    }
33	    svg {
34	      width: min(400px, 80vmin);
35	      height: min(400px, 80vmin);
36	      overflow: visible;
37	      cursor: pointer;
38	      user-select: none;
39	      -webkit-tap-highlight-color: transparent;
40	      transition: filter 0.3s ease;
41	    }
42	    .circle-btn:hover svg {
43	      filter: brightness(1.08);
44	    }
45	    .ambient {
46	      fill: var(--circle-hue);
47	      opacity: 0.12;
48	      filter: blur(30px);
49	      animation: breathe var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
50	      transform-origin: 200px 200px;
51	      will-change: transform, opacity;
52	    }
53	    .core {
54	      animation: pulse var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
55	      transform-origin: 200px 200px;
56	      filter: url(#glow);
57	      will-change: transform, opacity;
58	    }
59	    .highlight {
60	      fill: url(#highlightGradient);
61	      transform-origin: 200px 200px;
62	      animation: pulse var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
63	      pointer-events: none;
64	      will-change: transform, opacity;
65	    }
66	    .ring {
67	      fill: none;
68	      stroke: var(--circle-hue);
69	      stroke-width: 2.5;
70	      transform-origin: 200px 200px;
71	      animation: ripple var(--cycle) cubic-bezier(0.2, 0.6, 0.4, 1) infinite;
72	      will-change: transform, opacity, stroke-width;
73	    }
74	    .ring--delay-1 {
75	      animation-delay: calc(var(--cycle) / 3);
76	    }
77	    .ring--delay-2 {
78	      animation-delay: calc(var(--cycle) / 3 * 2);
79	    }
80	    @keyframes pulse {
81	      0%, 100% {
82	        transform: scale(1);
83	        opacity: 0.9;
84	      }
85	      50% {
86	        transform: scale(1.05);
87	        opacity: 1;
88	      }
89	    }
90	    @keyframes breathe {
91	      0%, 100% {
92	        transform: scale(0.95);
93	        opacity: 0.1;
94	      }
95	      50% {
96	        transform: scale(1.1);
97	        opacity: 0.18;
98	      }
99	    }
100	    @keyframes ripple {
101	      0% {
102	        transform: scale(1);
103	        opacity: 0.6;
104	        stroke-width: 2.5;
105	      }
106	      100% {
107	        transform: scale(1.35);
108	        opacity: 0;
109	        stroke-width: 0.5;
110	      }
111	    }
112	    body.paused .core,
113	    body.paused .ring,
114	    body.paused .ambient,
115	    body.paused .highlight {
116	      animation-play-state: paused;
117	    }
118	    @media (prefers-reduced-motion: reduce) {
119	      /* Avoid a flash of motion before JS applies the paused state. */
120	      .core,
121	      .ring,
122	      .ambient,
123	      .highlight {
124	        animation-play-state: paused;
125	      }
126	    }
127	    .speed-label {
128	      color: var(--circle-hue);
129	      font-family: system-ui, sans-serif;
130	      font-size: 0.85rem;
131	      letter-spacing: 0.05em;
132	      opacity: 0.85;
133	      user-select: none;
134	      text-align: center;
135	    }
136	    .hint {
137	      display: block;
138	      margin-top: 4px;
139	      font-size: 0.7rem;
140	      opacity: 0.85;
141	    }
142	    .controls {
143	      display: flex;
144	      align-items: center;
145	      gap: 12px;
146	      max-width: min(320px, 90vw);
147	    }
148	    .pause-btn {
149	      display: inline-flex;
150	      align-items: center;
151	      justify-content: center;
152	      width: 36px;
153	      height: 36px;
154	      padding: 0;
155	      border-radius: 50%;
156	      border: 1px solid var(--circle-hue);
157	      background: transparent;
158	      color: var(--circle-hue);
159	      cursor: pointer;
160	      transition: background 0.2s ease;
161	    }
162	    .pause-btn:hover {
163	      background: rgba(142, 197, 255, 0.15);
164	    }
165	    .pause-btn:focus-visible {
166	      outline: 2px solid var(--circle-hue);
167	      outline-offset: 2px;
168	    }
169	    .pause-btn svg {
170	      width: 14px;
171	      height: 14px;
172	    }
173	    .circle-btn {
174	      display: inline-flex;
175	      padding: 0;
176	      border: none;
177	      background: none;
178	      cursor: pointer;
179	      -webkit-tap-highlight-color: transparent;
180	      border-radius: 50%;
181	    }
182	    .circle-btn:focus-visible svg {
183	      outline: 2px solid var(--circle-hue);
184	      outline-offset: 8px;
185	      border-radius: 50%;
186	    }
187	  </style>
188	</head>
189	<body>
190	  <button type="button" class="circle-btn" id="circleBtn" aria-label="Pulsing blue circle animation. Click to change pulse speed." aria-describedby="speedText">
191	  <svg id="ae683f770" viewBox="0 0 400 400" focusable="false">
192	    <title>Pulsing blue circle animation</title>
193	    <defs>
194	      <radialGradient id="circleGradient" cx="35%" cy="35%" r="65%">
195	        <stop offset="0%" stop-color="#8ec5ff"/>
196	        <stop offset="55%" stop-color="#4a7dd9"/>
197	        <stop offset="100%" stop-color="#1f3a75"/>
198	      </radialGradient>
199	      <radialGradient id="highlightGradient" cx="32%" cy="28%" r="22%">
200	        <stop offset="0%" stop-color="#ffffff" stop-opacity="0.55"/>
201	        <stop offset="100%" stop-color="#ffffff" stop-opacity="0"/>
202	      </radialGradient>
203	      <filter id="glow" x="-80%" y="-80%" width="260%" height="260%">
204	        <feGaussianBlur in="SourceGraphic" stdDeviation="10" result="blur"/>
205	        <feColorMatrix in="blur" type="matrix"
206	          values="0 0 0 0 0.55  0 0 0 0 0.77  0 0 0 0 1  0 0 0 0.9 0" result="tintedBlur"/>
207	        <feMerge>
208	          <feMergeNode in="tintedBlur"/>
209	          <feMergeNode in="SourceGraphic"/>
210	        </feMerge>
211	      </filter>
212	    </defs>
213	    <circle class="ambient" cx="200" cy="200" r="160"/>
214	    <circle class="ring" cx="200" cy="200" r="140"/>
215	    <circle class="ring ring--delay-1" cx="200" cy="200" r="140"/>
216	    <circle class="ring ring--delay-2" cx="200" cy="200" r="140"/>
217	    <circle class="core" cx="200" cy="200" r="140" fill="url(#circleGradient)"/>
218	    <circle class="highlight" cx="200" cy="200" r="140"/>
219	  </svg>
220	  </button>
221	  <div class="controls">
222	    <button type="button" class="pause-btn" id="pauseBtn" aria-pressed="false" aria-label="Pause animation">
223	      <svg id="pauseIcon" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
224	        <path d="M6 4h4v16H6zM14 4h4v16h-4z"/>
225	      </svg>
226	    </button>
227	    <p class="speed-label" id="speedLabel">
228	      <span id="speedText" aria-live="polite">Normal speed</span>
229	      <span class="hint">Click circle to change speed</span>
230	    </p>
231	  </div>
232	  <script>
233	    const circleBtn = document.getElementById('circleBtn');
234	    const speedText = document.getElementById('speedText');
235	    const pauseBtn = document.getElementById('pauseBtn');
236	    const pauseIcon = document.getElementById('pauseIcon');
237	    const PLAY_ICON = '<path d="M8 5l11 7-11 7z"/>';
238	    const PAUSE_ICON = '<path d="M6 4h4v16H6zM14 4h4v16h-4z"/>';
239	    const speeds = [
240	      { value: '2.5s', name: 'Normal speed' },
241	      { value: '1.2s', name: 'Fast speed' },
242	      { value: '4.5s', name: 'Slow speed' },
243	    ];
244	    let speedIndex = 0;
245	    const reducedMotionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
246	    let manuallyPaused = reducedMotionQuery.matches;
247	
248	    function updateLabels() {
249	      const { name } = speeds[speedIndex];
250	      speedText.textContent = manuallyPaused ? `${name} (paused)` : name;
251	    }
252	
253	    function cycleSpeed() {
254	      speedIndex = (speedIndex + 1) % speeds.length;
255	      const { value } = speeds[speedIndex];
256	      circleBtn.style.setProperty('--cycle', value);
257	      // Restart animations from the beginning so the new speed feels immediate
258	      // instead of jumping mid-cycle.
259	      document.querySelectorAll('.core, .ring, .ambient, .highlight').forEach((el) => {
260	        el.style.animation = 'none';
261	        void el.offsetWidth;
262	        el.style.animation = '';
263	      });
264	      updateLabels();
265	    }
266	
267	    function applyPauseState() {
268	      document.body.classList.toggle('paused', document.hidden || manuallyPaused);
269	      pauseBtn.setAttribute('aria-pressed', String(manuallyPaused));
270	      pauseBtn.setAttribute('aria-label', manuallyPaused ? 'Resume animation' : 'Pause animation');
271	      pauseIcon.innerHTML = manuallyPaused ? PLAY_ICON : PAUSE_ICON;
272	      updateLabels();
273	    }
274	
275	    function togglePause() {
276	      manuallyPaused = !manuallyPaused;
277	      applyPauseState();
278	    }
279	
280	    circleBtn.addEventListener('click', cycleSpeed);
281	    pauseBtn.addEventListener('click', togglePause);
282	
283	    document.addEventListener('visibilitychange', () => {
284	      document.body.classList.toggle('paused', document.hidden || manuallyPaused);
285	    });
286	
287	    reducedMotionQuery.addEventListener('change', (e) => {
288	      manuallyPaused = e.matches;
289	      applyPauseState();
290	    });
291	
292	    applyPauseState();
293	  </script>
294	</body>
295	</html>
